import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            k = int(next(iterator))
        except StopIteration:
            break

        used = [False] * n
        pairs = []

        if k == n - 1:
            out_lines.append("-1")
            continue

        pairs.append((0, k))
        used[0] = True
        used[k] = True

        if k == 0:
            for i in range(1, n):
                if not used[i]:
                    partner = i ^ (n - 1)
                    if not used[partner]:
                        pairs.append((i, partner))
                        used[i] = True
                        used[partner] = True
        else:
            complement_k = k ^ (n - 1)
            pairs.append((complement_k, n - 1))
            used[complement_k] = True
            used[n - 1] = True

            for i in range(1, n):
                if not used[0] and not used[i]:
                    pass
                if not used[i]:
                    partner = i ^ (n)
                    if partner < n and not used[partner]:
                        pairs.append((i, partner))
            for i in range(1, n):
                if not i == 0 and not i == k and not i == complement_k and not i == n - 1:
                    if not used[i]:
                        partner = i ^ (n - 1)
                        if not used[partner]:
                            pairs.append((i, partner))
                            used[i] = True
                            used[partner] = True

        valid = True
        current_sum = 0
        for a, b in pairs:
            current_sum += (a & b)

        if current_sum != k:
            out_lines.append("-1")
        else:
            for a, b in pairs:
                out_lines.append(f"{a} {b}")

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == "__main__":
    solve()
